/bin/bash -lc "python - <<'PY'
import requests
hits=[]
page=1
url='https://quay.io/api/v1/repository/biocontainers/anndata/tag/?limit=100'
while url and len(hits)<50:
    r=requests.get(url,timeout=20); r.raise_for_status(); data=r.json()
    for t in data.get('tags',[]):
        if '0.11' in t['name'] or '0.10' in t['name']:
            hits.append((t['name'],t.get('last_modified'),t.get('manifest_digest'),t.get('is_manifest_list')))
    if data.get('has_additional'):
        # Quay API pagination via next_page? print keys
        url='https://quay.io/api/v1/repository/biocontainers/anndata/tag/?limit=100&page=%d'% (page+1)
        page+=1
        if page>20: break
    else:
        url=None
for h in hits[:100]: print('\\t'.join(map(str,h)))
print('count',len(hits),'pages',page)
PY"

