# Compute simple Welch t scores vs collapsed NT locally for guidance, then correlate and assign.
import h5py,numpy as np,pandas as pd
from scipy.sparse import csc_matrix
from scipy.optimize import linear_sum_assignment

def read_cat(f,path):
 g=f[path]; cats=[x.decode() if isinstance(x,bytes) else str(x) for x in g['categories'][:]]; return np.array([cats[int(c)] for c in g['codes'][:]])
def read(path):
 with h5py.File(path,'r') as f:
  X=csc_matrix((f['X/data'][:],f['X/indices'][:],f['X/indptr'][:]),shape=tuple(f['X'].attrs['shape'])).tocsr()
  var=np.array([x.decode() if isinstance(x,bytes) else str(x) for x in f['var/_index'][:]])
  guide=read_cat(f,'obs/guide'); target=read_cat(f,'obs/target_gene') if 'target_gene' in f['obs'] else None
 return X,var,guide,target
Xr,vr,gr,tr=read('inputs/perturb.seq.align.q1.ref.h5ad'); Xq,vq,gq,_=read('inputs/perturb.seq.align.q1.query.h5ad')
common,ir,iq=np.intersect1d(vr,vq,return_indices=True); Xr=Xr[:,ir]; Xq=Xq[:,iq]
ref=sorted([g for g in set(gr) if not g.startswith('NT-')]); qry=sorted([g for g in set(gq) if not g.startswith('NT-')], key=lambda x:int(x[5:]))
tmap=pd.DataFrame({'guide':gr,'target':tr}).drop_duplicates().set_index('guide')['target'].to_dict()
def stats(X,guides,labels):
 nt_idx=np.flatnonzero(np.char.startswith(guides.astype(str),'NT-'))
 Xnt=X[nt_idx]
 nt_mean=np.asarray(Xnt.mean(0)).ravel()
 nt2=np.asarray(Xnt.multiply(Xnt).mean(0)).ravel(); nt_var=np.maximum(nt2-nt_mean**2,0); nnt=len(nt_idx)
 scores=[]; lfc=[]
 for lab in labels:
  idx=np.flatnonzero(guides==lab); Xg=X[idx]
  m=np.asarray(Xg.mean(0)).ravel(); m2=np.asarray(Xg.multiply(Xg).mean(0)).ravel(); v=np.maximum(m2-m**2,0); n=len(idx)
  diff=m-nt_mean
  se=np.sqrt(v/max(n,1)+nt_var/max(nnt,1))+1e-9
  scores.append(diff/se); lfc.append(diff)
 return np.vstack(scores), np.vstack(lfc)
Rs,Rl=stats(Xr,gr,ref); Qs,Ql=stats(Xq,gq,qry)
def corr(A,B):
 A=A-A.mean(1,keepdims=True); B=B-B.mean(1,keepdims=True); return A@B.T/np.outer(np.sqrt((A*A).sum(1)),np.sqrt((B*B).sum(1)))
def report(C,name):
 rows,cols=linear_sum_assignment(-C); inv={ref[j]:qry[i] for i,j in zip(rows,cols)}; miss=[ref[j] for j in set(range(len(ref)))-set(cols)]
 print('\\n',name,'missing',miss)
 for t in ['PABPC1','NUDT21','LEO1']:
  rg=[g for g in ref if tmap[g]==t][0]; j=ref.index(rg)
  print(t,rg,'assign',inv.get(rg),'top',[(qry[i],round(C[i,j],3)) for i in np.argsort(C[:,j])[::-1][:10]])
for name,R,Q in [('score',Rs,Qs),('diff',Rl,Ql)]:
 for prep in ['raw','center','zgenes','rank']:
  RR=R.copy(); QQ=Q.copy()
  if prep=='center': RR-=RR.mean(0); QQ-=QQ.mean(0)
  elif prep=='zgenes': RR=(RR-RR.mean(0))/(RR.std(0)+1e-6); QQ=(QQ-QQ.mean(0))/(QQ.std(0)+1e-6)
  elif prep=='rank':
   RR=np.apply_along_axis(lambda x: pd.Series(x).rank().values,0,RR); QQ=np.apply_along_axis(lambda x: pd.Series(x).rank().values,0,QQ); RR-=RR.mean(0); QQ-=QQ.mean(0)
  var=np.vstack([RR,QQ]).var(0)
  for n in [11858,3000,1000,500,200]:
   idx=np.argsort(var)[-min(n,len(var)):]
   report(corr(QQ[:,idx],RR[:,idx]), f'{name}_{prep}_{n}')
PY"

